    def _window(self, lo, hi, clause):
        """Fetch one OBJECTID window; if the server truncates or rejects it, split it in half.
        A small window the server still rejects is fetched without the owner/use filter
        (the caller filters every row anyway), and only if that fails too is it skipped."""
        rng = "OBJECTID BETWEEN %d AND %d AND %s" % (lo, hi, self._co_sql())
        params = {"outFields": self.OUT, "returnGeometry": "false", "returnCentroid": "true", "outSR": 4326, "f": "json"}
        small = hi - lo < 1500
        data = None
        try:
            data = _get_json(self.url + "/query", dict(params, where=rng + " AND " + clause), retries=2 if small else 1, timeout=75)
        except RuntimeError:
            if small:
                try:
                    data = _get_json(self.url + "/query", dict(params, where=rng), retries=2, timeout=75)
                except RuntimeError as e:
                    self.skipped.append((lo, hi))
                    print("   %s: SKIPPED record IDs %d-%d (%s)" % (self.county_key, lo, hi, str(e)[-80:]), flush=True)
                    return
        if data is not None and not data.get("exceededTransferLimit"):
            for ft in data.get("features", []):
                yield self._normalize(ft)
            return
        if hi <= lo:
            return
        mid = (lo + hi) // 2
        yield from self._window(lo, mid, clause)
        yield from self._window(mid + 1, hi, clause)

